// Package oui names the maker of a hardware address from the IEEE registry
// of address blocks (MA-L, MA-M and MA-S). The table is generated by
// `go generate` and embedded, compressed.
package oui

//go:generate go run ./gen

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"strings"
	"sync"
)

//go:embed oui.txt.gz
var table []byte

var (
	once    sync.Once
	vendors map[string]string // upper-case hex prefix (6, 7 or 9 digits) -> name
)

func load() {
	vendors = map[string]string{}
	zr, err := gzip.NewReader(bytes.NewReader(table))
	if err != nil {
		return
	}
	sc := bufio.NewScanner(zr)
	for sc.Scan() {
		if k, v, ok := strings.Cut(sc.Text(), "\t"); ok {
			vendors[k] = v
		}
	}
}

// Lookup returns the vendor of a hardware address ("7c:39:53:d0:ed:67"),
// or "" when the registry does not know it. The longest block wins: an
// MA-S block (36 bits) inside an MA-L block (24 bits) names the smaller
// owner.
func Lookup(mac string) string {
	once.Do(load)
	hex := strings.ToUpper(strings.NewReplacer(":", "", "-", "", ".", "").Replace(mac))
	for _, n := range []int{9, 7, 6} {
		if len(hex) >= n {
			if v, ok := vendors[hex[:n]]; ok {
				return v
			}
		}
	}
	return ""
}

// Size is the number of address blocks in the table.
func Size() int {
	once.Do(load)
	return len(vendors)
}
